INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23401, 'Mark 8:20', 'Mark', 8, 20, '&nbsp;”او چې کله مې اووۀ روټۍ څلور زرو کسانو ته ماتې کړې، نو تاسو د پاتې شوو ټوکړو نه څومره لوئې ټوکرۍ ډکې کړې وې؟“ نو هغوئ جواب ورکړو، ”اووۀ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23402, 'Mark 8:21', 'Mark', 8, 21, '&nbsp;نو هغۀ وفرمائيل چې، ”لا تر اوسه هم نۀ پوهېږئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23403, 'Mark 8:22', 'Mark', 8, 22, '&nbsp;کله چې هغوئ بيتِ‌صيدا ته ورسېدل نو څۀ خلقو عيسىٰ له يو ړوند سړے راوستو او مِنت يې ورته وکړو چې په هغۀ خپل لاس کېږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23404, 'Mark 8:23', 'Mark', 8, 23, '&nbsp;بيا هغۀ ړوند سړے د لاسه ونيولو او د کلى نه يې بهر بوتلو. او د هغۀ په سترګو يې لاړې پورې کړې او لاسونه يې پرې کېښودل او تپوس يې ترې وکړو چې، ”تا ته څۀ ښکارى او کۀ نه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23405, 'Mark 8:24', 'Mark', 8, 24, '&nbsp;د سړى سترګې بينا شوې او وې وئيل، ”زۀ خلق وينم خو هغوئ ګرځى راګرځى او د ونو په شان ښکارى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23406, 'Mark 8:25', 'Mark', 8, 25, '&nbsp;عيسىٰ بيا د هغۀ په سترګو لاسونه کېښودل او د هغۀ سترګې يې کولاو کړې، نو د هغۀ نظر ټيک شو او هر څۀ يې صفا وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23407, 'Mark 8:26', 'Mark', 8, 26, '&nbsp;بيا عيسىٰ هغه کور ته رُخصت کړو او ورته يې وفرمائيل چې، ”کور ته د تلو په لار کښې په کلى کښې مۀ ګرځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23408, 'Mark 8:27', 'Mark', 8, 27, '&nbsp;عيسىٰ د خپلو مريدانو سره قيصريه فيليپى ته لاړو. هغۀ په لاره د خپلو مريدانو نه تپوس وکړو چې، ”خلق څۀ وائى چې زۀ څوک يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23409, 'Mark 8:28', 'Mark', 8, 28, '&nbsp;هغوئ جواب ورکړو، ”څوک دې بپتسمه ورکوونکے يحيىٰ، او څوک دې الياس، او څوک دې د نبيانو نه يو نبى ګڼى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23410, 'Mark 8:29', 'Mark', 8, 29, '&nbsp;هغۀ د هغوئ نه تپوس وکړو چې، ”تاسو څۀ وايئ چې زۀ څوک يم؟“ پطروس جواب ورکړو چې، ”تۀ مسيح يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23411, 'Mark 8:30', 'Mark', 8, 30, '&nbsp;بيا هغۀ هغوئ په سختۍ سره منع کړل چې، د هغۀ په حقله هيچا ته مۀ وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23412, 'Mark 8:31', 'Mark', 8, 31, '&nbsp;بيا يې هغوئ ته تعليم شروع کړو چې، ”اِبن آدم به خامخا ډيرې سختۍ وزغمى مشران او مشران اِمامان او د شرعې عالمان به يې رد کړى او هغه به ووژلے شى، او په درېمه ورځ به راژوندے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23413, 'Mark 8:32', 'Mark', 8, 32, '&nbsp;هغۀ دا خبره په صفا ټکو کښې ووئيله. بيا پطروس هغه د لاس نه ونيوو او يوې خوا ته يې بوتلو او د داسې خبرو نه يې منع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23414, 'Mark 8:33', 'Mark', 8, 33, '&nbsp;خو عيسىٰ مخ راواړولو، خپلو مريدانو ته يې وکتل او پطروس يې ورټلو. او ورته يې وفرمائيل چې، ”رانه لرې شه شېطانه، تۀ د بنى آدمو په شان سوچ کوې، نه چې د خُدائ پاک په شان.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23415, 'Mark 8:34', 'Mark', 8, 34, '&nbsp;هغۀ خلق او خپل مريدان راوبلل او هغوئ ته يې وفرمائيل، ”کۀ څوک زما مريدان جوړېدل غواړى، هغه دې د خپل ځان نه منکر شى، خپله سولۍ دې راواخلى او ما پسې دې راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23416, 'Mark 8:35', 'Mark', 8, 35, '&nbsp;څوک چې خپل ځان ساتل غواړى هغه به يې بائيلى، خو څوک چې د زيرى او زما د خاطره خپل ژوند بائيلى، نو هغه به يې بچ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23417, 'Mark 8:36', 'Mark', 8, 36, '&nbsp;کۀ څوک د خپل ابدى ژوند په بدله کښې ټوله دُنيا ومومى نو هغۀ ځان ته څۀ فائده حاصلوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23418, 'Mark 8:37', 'Mark', 8, 37, '&nbsp;يا د خپل ژوند په بدله کښې هغه څۀ ورکولے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23419, 'Mark 8:38', 'Mark', 8, 38, '&nbsp;په دې زناکاره او ګناهګاره زمانه کښې څوک چې په ما او زما په کلام شرميږى، نو اِبن آدم به هم د هغوئ نه وشرميږى کله چې هغه د خپل پلار جلال کښې د پاکو فرښتو سره راشى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23420, 'Mark 9:1', 'Mark', 9, 1, '&nbsp;او عيسىٰ هغوئ ته وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم چې دلته ځينې داسې کسان ولاړ دى چې هغوئ به تر هغې نۀ مرى ترڅو چې د خُدائ پاک بادشاهى په قدرت سره په راتلو ونۀ وينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23421, 'Mark 9:2', 'Mark', 9, 2, '&nbsp;شپږ ورځې پس عيسىٰ د ځان سره پطروس يعقوب او يوحنا روان کړل او يو اوچت غرۀ ته يې وخېژول او د هغوئ په وړاندې د هغۀ شکل بدل کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23422, 'Mark 9:3', 'Mark', 9, 3, '&nbsp;د هغۀ جامې برېښېدونکې سپينې شوې، داسې سپينې چې د زمکې په مخ داسې چا نۀ شوې سپينولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23423, 'Mark 9:4', 'Mark', 9, 4, '&nbsp;نو هغوئ ته هلته الياس او موسىٰ ښکاره شو چې د عيسىٰ سره يې خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23424, 'Mark 9:5', 'Mark', 9, 5, '&nbsp;نو پطروس عيسىٰ ته ووئيل چې، ”مالِکه، زمونږ دپاره دلته پاتې کېدل څومره ښۀ دى. مونږ له اجازه راکړه چې درې جونګړې جوړې کړُو، يوه ستا دپاره، يوه د موسىٰ دپاره او يوه د الياس دپاره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23425, 'Mark 9:6', 'Mark', 9, 6, '&nbsp;هغه نور نۀ پوهېدو چې څۀ ووائى ځکه چې هغوئ ټول يرې اخستى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23426, 'Mark 9:7', 'Mark', 9, 7, '&nbsp;بيا يوه وريځ راخوره شوه او په هغوئ يې سورے وکړو او د وريځې نه يو آواز راغلو، ”دا زما محبوب زوئ دے. د هغۀ خبرې واورئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23427, 'Mark 9:8', 'Mark', 9, 8, '&nbsp;ناګهانه چې کله هغوئ ګېرچاپېره نظر واچولو نو څوک يې هم ونۀ ليدل خو صرف عيسىٰ د هغوئ سره پاتې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23428, 'Mark 9:9', 'Mark', 9, 9, '&nbsp;نو کله چې هغوئ د غرۀ نه راکوزېدل نو عيسىٰ هغوئ ته حکم ورکړو چې، ”دا هر څۀ چې مو وليدل د دې په حقله تر هغې چا ته څۀ مۀ وايئ ترڅو چې اِبن آدم د مړو نه بيا ژوندے پورته کړے شوے نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23429, 'Mark 9:10', 'Mark', 9, 10, '&nbsp;هغوئ دا خبره ځان سره وساتله او په خپلو کښې يې بحث کولو چې د مړو نه د بيا راپاڅېدلو څۀ مطلب کېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23430, 'Mark 9:11', 'Mark', 9, 11, '&nbsp;نو هغوئ د هغۀ نه تپوس وکړو چې، ”بيا زمونږ د شرعې عالمان دا ولې وائى چې الياس به ضرور وړومبے راځى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23431, 'Mark 9:12', 'Mark', 9, 12, '&nbsp;هغۀ جواب ورکړو، ”آو، الياس به وړومبے راځى چې هر څيز سم کړى، خو په صحيفو کښې ليکلى دى چې په اِبن آدم به ډيرې سختۍ تېرې شى او په سپک نظر به ورته وکتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23432, 'Mark 9:13', 'Mark', 9, 13, '&nbsp;خو زۀ تاسو ته وايم چې الياس خو راغلے دے او هر څۀ چې د هغوئ خوښ وُو هغه يې ورسره کړى هم دى لکه چې د هغۀ په حقله صحيفو فرمائيلى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23433, 'Mark 9:14', 'Mark', 9, 14, '&nbsp;چې هغوئ مريدانو ته واپس راغلل نو ګڼ خلق يې ورسره وليدل چې په کښې د شرعې عالمان هم وُو او بحث يې ورسره کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23434, 'Mark 9:15', 'Mark', 9, 15, '&nbsp;هر کله چې هغوئ عيسىٰ وليدلو نو ټول خلق حېران شول او په منډه هغۀ له ستړى مشى له ورغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23435, 'Mark 9:16', 'Mark', 9, 16, '&nbsp;هغۀ تپوس ترې وکړو چې، ”دا د څۀ بحث روان دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23436, 'Mark 9:17', 'Mark', 9, 17, '&nbsp;په ګڼه کښې يو سړى جواب ورکړو، ”اُستاذه، ما خپل زوئ تا له راوستے دے. هغه پيريانو نيولے دے چې ورنه خبرې نۀ شى کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23437, 'Mark 9:18', 'Mark', 9, 18, '&nbsp;کله چې پرې چپه راشى نو په زمکه يې راوولى او په خولۀ يې ځګونه راشى، غاښونه چيچى، او بدن يې اېغ نېغ شى. ما ستا مريدانو ته خواست وکړو چې دا ترې نه وباسئ خو هغوئ پاتې راغلل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23438, 'Mark 9:19', 'Mark', 9, 19, '&nbsp;عيسىٰ جواب ورکړو، ”اے بې‌ايمانه پيړۍ، زۀ به ترڅو تاسو سره يم او زۀ به ترڅو تاسو زغمم؟ دے ما له راولئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23439, 'Mark 9:20', 'Mark', 9, 20, '&nbsp;نو هغوئ هغه هلک هغۀ له راوستو. او څۀ وخت چې پيرى هغه وليدو نو د هغۀ وجود يې تاو راتاو کړو او هغه په زمکه پرېوتو، ورغړېدو او په خولۀ يې ځګونه راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23440, 'Mark 9:21', 'Mark', 9, 21, '&nbsp;عيسىٰ د هغۀ د پلار نه تپوس وکړو چې، ”څومره موده کيږى چې دے په دې حال دے؟“ هغۀ جواب ورکړو چې، ”د وړوکوالې راسې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23441, 'Mark 9:22', 'Mark', 9, 22, '&nbsp;څو ځله يې د هلاکولو دپاره اور او اوبو ته هم غورزولے دے، او کۀ تۀ څۀ کولے شې نو په مونږ رحم وکړه او مدد راسره وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23442, 'Mark 9:23', 'Mark', 9, 23, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”تۀ ولې داسې وائې چې کۀ تۀ څۀ کولے شې؟ د چا چې پوره ايمان وى د هغۀ دپاره هر څۀ ممکن دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23443, 'Mark 9:24', 'Mark', 9, 24, '&nbsp;د هلک پلار چغې کړې چې، ”زۀ ايمان لرم، خو زما کمزورے ايمان مضبوط کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23444, 'Mark 9:25', 'Mark', 9, 25, '&nbsp;کله چې عيسىٰ وليدل چې ګڼ خلق رانزدې کيږى نو هغۀ هغه پيرے ورټلو. هغۀ وفرمائيل، ”اے ګونګا او کُوڼ پيريه، زۀ درته حکم کوم، چې د دۀ نه راوځه او بيا کله هم مۀ ورننوځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23445, 'Mark 9:26', 'Mark', 9, 26, '&nbsp;هغۀ په زوره چغې کړې او ډېر يې تاو راتاو کړو او بيا پيرے ترې ووتو او هلک لکه د مړى په شان پرېوتو، بلکې ډېرو وئيل چې، ”دے مړ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23446, 'Mark 9:27', 'Mark', 9, 27, '&nbsp;خو عيسىٰ هغه د لاسه ونيولو او په پښو يې ودرولو او هغه ودرېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23447, 'Mark 9:28', 'Mark', 9, 28, '&nbsp;بيا عيسىٰ دننه لاړو او د هغۀ مريدانو ترې ځان له تپوس وکړو چې، ”دا مونږ ولې نۀ شُو شړلے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23448, 'Mark 9:29', 'Mark', 9, 29, '&nbsp;هغۀ ورته وفرمائيل، ”دا قِسم صرف او صرف د دُعا په وسيله شړلے کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23449, 'Mark 9:30', 'Mark', 9, 30, '&nbsp;بيا هغوئ د هغې علاقې نه لاړل او د ګليل نه واوړېدل. عيسىٰ دا غوښتل چې هيڅوک پرې خبر نۀ شى چې چرته دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
